@file:Suppress("OPT_IN_USAGE")

package naksha.model.objects

import naksha.base.AnyObject
import naksha.base.NullableEnum
import naksha.base.NullableProperty
import kotlin.js.JsExport
import kotlin.js.JsName

/**
 * A JSON property of features that is materialized as a custom [Member] and, except for booleans, indexed.
 *
 * Mappings are declared in [NakshaCollection.customIndexMapping]. Member and index names are generated by the Hub, the
 * client only declares the [jsonPath] and the [dataType].
 * @since 3.0
 */
@JsExport
open class CustomIndexMapping() : AnyObject() {

    /**
     * Create a mapping.
     * @param jsonPath the path of the value in the feature.
     * @param dataType the type of the member.
     * @since 3.0
     */
    @JsName("of")
    constructor(jsonPath: JsonPath, dataType: MemberType) : this() {
        this.jsonPath = jsonPath
        this.dataType = dataType
    }

    /**
     * The path of the value in the feature, for example `["properties", "speedLimit"]`.
     * @since 3.0
     */
    var jsonPath: JsonPath? by JSON_PATH

    /**
     * The type of the member.
     * @since 3.0
     */
    var dataType: MemberType? by DATA_TYPE

    companion object CustomIndexMapping_C {
        private val JSON_PATH = NullableProperty<CustomIndexMapping, JsonPath>(JsonPath::class)
        private val DATA_TYPE = NullableEnum<CustomIndexMapping, MemberType>(MemberType::class)
    }
}
